**Gates before launch**

I run four gates in the main session. The full run starts only after all four pass. First, the grader selftest: grade.py must score 100% when it grades answers.json against itself, and it must score 0 or fail on an empty submission and on a submission with every label deliberately wrong. Second, the control: grade.py regrades round 3's saved outputs, and the numbers must match the round 3 Measured column in spe/prediction-log.md exactly. Any drift means the grader changed, and I halt. Third, the dry run: I launch this script with `{dryRunCells: [{config:'B',ticket:'T01'},{config:'C2',ticket:'T01'},{config:'C2',ticket:'T02'}], runId:'r04-dry-1'}`. That run goes through every phase. I confirm that the schemas hold, that the peek scan finds all 3 trial transcripts, and that grade.py results map back to each nonce. I also read the real per-call cost from that run. Fourth, the budget check: I use the dry-run costs to work out whether the 500 base trials plus the reserve for grading and judging fit under $40. If they do not fit, I stop and ask you, because that decision is yours. If everything passes, I commit `SPE r04 evaluate (harness)`. Then I launch with `{gatesPassed:true, runId:'r04-main-1', costPerTrial:<measured>, costPerJudgeBatch:<measured>, ...}`.

Some details here are my assumptions, because I was told not to read any files. That includes r03-workflow.js. These need checking against r03 before the dry run:
- the tickets folder path
- the configs folder path
- the runs and results folder paths
- the tool stub setup
- how grade.py is called (the grader agent is told to call it the same way r03 did)

The trial model defaults to Opus. If the plan names a different model, pass it as `args.trialModel`. All spend figures are estimates. The script cannot measure real spend.

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4 eval. Configs B and C2 on 50 tickets, 5 trials per cell, code grader first, blind Opus tone judge second, $40 estimated spend cap.',
  phases: ['Preflight', 'Trials', 'Peek scan', 'Code grade', 'Split cells', 'Tone judge', 'Failure analysis', 'Completeness critic', 'Record'],
};

// Round constants. The round number lives only in ROUND.
const ROUND = 4;
const pad = n => String(n).padStart(2, '0');
const R = `r${pad(ROUND)}`;
const A = (typeof args === 'object' && args !== null) ? args : {};
const DRY = Array.isArray(A.dryRunCells) && A.dryRunCells.length > 0;

const CONFIGS = ['B', 'C2'];
const EXPECTED_TICKETS = 50;
const TRIALS_PER_CELL = DRY ? 1 : 5;
const MAX_TRIALS_PER_CELL = DRY ? 1 : 10; // split cells grow to at most 10 trials
const CAP_USD = 40;
const SCAN_BATCH = 25;
const FAIL_SAMPLE_CAP = 150;

const TRIAL_MODEL = A.trialModel || 'opus';
const JUDGE_MODEL = 'opus';
const HELPER_MODEL = 'opus';

// Estimated USD per call. The script cannot meter spend. Pass dry-run measurements in args.
const COST = {
  trial: A.costPerTrial ?? 0.05,
  scanBatch: A.costPerScanBatch ?? 0.10,
  grade: A.costPerGrade ?? 0.30,
  judgeBatch: A.costPerJudgeBatch ?? 0.15,
  helper: A.costPerHelper ?? 0.50,
};

const RUN_ID = A.runId || `${R}-${DRY ? 'dry' : 'main'}`; // pass a fresh runId on every launch
const P = {
  tickets: 'spe/evals/tasks/tickets',
  configs: 'spe/evals/configs',
  grader: 'spe/evals/graders/grade.py',
  answers: 'spe/evals/tasks/answers.json',
  judge: 'spe/evals/graders/judge.md',
  failures: 'spe/failures.md',
  prediction: `spe/predictions/${R}.yaml`,
  plan: `spe/plans/${R}.md`,
  prevHarness: `spe/evals/harness/r${pad(ROUND - 1)}-workflow.js`,
  runDir: `spe/evals/runs/${RUN_ID}`,
  results: `spe/evals/results/${RUN_ID}.json`,
};
const LEAK_MARKERS = ['answers.json', 'spe/evals/graders'];

// ---------- Helpers ----------
let haltReason = null;
function halt(reason) {
  if (!haltReason) { haltReason = reason; log(`HALT: ${reason}`); }
}

const ledger = { estSpent: 0, held: 0, skips: [] };
function reserve(kind, usd, what, fromHeld = false) {
  if (fromHeld) ledger.held = Math.max(0, ledger.held - usd);
  if (ledger.estSpent + ledger.held + usd > CAP_USD) {
    ledger.skips.push({ kind, what, usd });
    log(`SKIP ${kind} ${what}: est spend $${(ledger.estSpent + usd).toFixed(2)} plus $${ledger.held.toFixed(2)} held would cross the $${CAP_USD} cap`);
    return false;
  }
  ledger.estSpent += usd;
  return true;
}

async function call(prompt, opts) {
  try { return await agent(prompt, opts); }
  catch (e) { log(`agent error in ${opts.label}: ${e && e.message ? e.message : e}`); return null; }
}

function hash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
function shuffled(arr, seed) {
  const a = arr.slice();
  let x = hash(seed) || 1;
  for (let i = a.length - 1; i > 0; i--) {
    x ^= x << 13; x ^= x >>> 17; x ^= x << 5; x >>>= 0;
    const j = x % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}
function rate(xs) {
  const v = xs.filter(x => typeof x === 'boolean');
  return v.length ? v.filter(Boolean).length / v.length : null;
}
const cellKey = t => `${t.config}/${t.ticket}`;

// ---------- Schemas ----------
const PRE_SCHEMA = {
  type: 'object',
  required: ['tickets', 'configs_present', 'prediction_committed', 'plan_committed', 'prediction_clean', 'notes'],
  properties: {
    tickets: { type: 'array', items: { type: 'object', required: ['id', 'path'], properties: { id: { type: 'string' }, path: { type: 'string' } } } },
    configs_present: { type: 'array', items: { type: 'string' } },
    prediction_committed: { type: 'boolean' },
    plan_committed: { type: 'boolean' },
    prediction_clean: { type: 'boolean' },
    notes: { type: 'string' },
  },
};
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['nonce', 'config', 'ticket_id', 'label', 'reply', 'tools_called', 'files_read'],
  properties: {
    nonce: { type: 'string' },
    config: { type: 'string', enum: CONFIGS },
    ticket_id: { type: 'string' },
    label: {
      type: 'object', required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tools_called: { type: 'array', items: { type: 'string' } },
    files_read: { type: 'array', items: { type: 'string' } },
  },
};
const SCAN_SCHEMA = {
  type: 'object', required: ['results'],
  properties: {
    results: { type: 'array', items: {
      type: 'object', required: ['nonce', 'transcript_found', 'outside_reads'],
      properties: { nonce: { type: 'string' }, transcript_found: { type: 'boolean' }, outside_reads: { type: 'array', items: { type: 'string' } } },
    } },
  },
};
const GRADE_SCHEMA = {
  type: 'object', required: ['exit_code', 'summary_line', 'stderr_tail', 'results'],
  properties: {
    exit_code: { type: 'integer' },
    summary_line: { type: 'string' },
    stderr_tail: { type: 'string' },
    results: { type: 'array', items: {
      type: 'object', required: ['nonce', 'category_ok', 'priority_ok'],
      properties: { nonce: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } },
    } },
  },
};
const JUDGE_SCHEMA = {
  type: 'object', required: ['verdicts'],
  properties: {
    verdicts: { type: 'array', items: {
      type: 'object', required: ['reply_id', 'tone_pass', 'reason'],
      properties: { reply_id: { type: 'string' }, tone_pass: { type: 'boolean' }, reason: { type: 'string' } },
    } },
  },
};
const FAIL_SCHEMA = {
  type: 'object', required: ['failure_types', 'grader_suspects'],
  properties: {
    failure_types: { type: 'array', items: {
      type: 'object', required: ['id', 'is_new', 'name', 'kind', 'counts', 'example_nonces', 'what', 'how_to_spot', 'fix'],
      properties: {
        id: { type: 'string' }, is_new: { type: 'boolean' }, name: { type: 'string' }, kind: { type: 'string' },
        counts: { type: 'object' }, example_nonces: { type: 'array', items: { type: 'string' } },
        what: { type: 'string' }, how_to_spot: { type: 'string' }, fix: { type: 'string' },
      },
    } },
    grader_suspects: { type: 'array', items: {
      type: 'object', required: ['nonce', 'why'], properties: { nonce: { type: 'string' }, why: { type: 'string' } },
    } },
  },
};
const CRITIC_SCHEMA = {
  type: 'object', required: ['complete', 'gaps', 'unmeasured_predictions'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'string' } },
    unmeasured_predictions: { type: 'array', items: { type: 'string' } },
  },
};
const RECORD_SCHEMA = {
  type: 'object', required: ['ok', 'written'],
  properties: { ok: { type: 'boolean' }, written: { type: 'array', items: { type: 'string' } } },
};

// ---------- Prompts ----------
function preflightPrompt() {
  return [
    `SPE ${R} preflight. Check the repo and report. Change nothing.`,
    `1. List the ticket files in ${P.tickets}. Return each ticket id (the file name without its extension) and its repo-relative path.`,
    `2. Report which of these config folders exist under ${P.configs}: ${CONFIGS.join(', ')}.`,
    `3. Use git to report whether ${P.prediction} and ${P.plan} each appear in at least one commit, and whether ${P.prediction} has no uncommitted changes.`,
    'Do not open the answer file or the graders. Put anything unusual in notes.',
  ].join('\n');
}

function trialPrompt(t) {
  return [
    `TRIAL-MARKER ${t.nonce}`,
    `You are one trial in an SPE eval. Run config ${t.config} on ticket ${t.ticket}.`,
    `1. Read the config folder ${P.configs}/${t.config}/. Its prompt file is your whole instruction set for this task. Use only the tools that folder defines, and take their results from the tool stubs in that folder.`,
    `2. Read the ticket file ${t.path}.`,
    '3. Do what the config prompt asks. Return the ticket label (category and priority) and the customer reply.',
    'Read only those two locations. Do not open, list, or search anything else in the spe folder or in git history. Do not write files.',
    'Put every path you opened in files_read. Put each config tool you used in tools_called. Copy the nonce exactly.',
  ].join('\n');
}

function allowedFor(t) { return [`${P.configs}/${t.config}/`, t.path]; }

function scanPrompt(batch) {
  const rows = batch.map(t => `- nonce ${t.nonce} | allowed: ${allowedFor(t).join(' , ')}`).join('\n');
  return [
    'SPE peek scan. You check eval trial transcripts for reads the trials were not allowed to make.',
    'Transcripts are .jsonl files under $CLAUDE_CONFIG_DIR/projects when that variable is set, and under ~/.claude/projects. Search both.',
    'For each nonce below, find the transcript whose first user message begins with the text TRIAL-MARKER, then a space, then that nonce. Ignore every other transcript that mentions the nonce. Ignore this scan transcript and any transcript whose first message begins with "SPE peek scan".',
    'In the trial transcript, collect every path the agent touched through any tool. That includes Read, Glob, Grep, LS, and Bash commands such as cat, head, ls, find, grep, rg, git show, and git log -p.',
    'Report only the paths inside the spe folder that the nonce\'s allowed list does not cover. Report what the transcript shows. Do not judge intent.',
    'Set transcript_found to false when you cannot find the trial transcript.',
    rows,
  ].join('\n');
}

function gradePrompt(config, tag, records) {
  const file = `${P.runDir}/${config}-${tag}.jsonl`;
  return [
    `SPE ${R} code grade for config ${config} (${tag}).`,
    `1. Write the records below to ${file}, one JSON object per line. If grade.py expects a different input shape, convert them with a small script and keep nonce as the record key.`,
    `2. Run ${P.grader} with python3 -I on that file against ${P.answers}, the same way ${P.prevHarness} runs it. Check the script's --help if the call is unclear.`,
    '3. Return one result per record with the category_ok and priority_ok values grade.py reports. Copy summary_line from the grade.py output exactly.',
    'Do not edit grade.py, the answer file, or the records. Do not grade anything by hand. If grade.py fails, return its exit code and the last lines of stderr, with an empty results list.',
    'Records:',
    records.map(r => JSON.stringify(r)).join('\n'),
  ].join('\n');
}

function judgePrompt(tk, order) {
  return [
    `SPE ${R} tone judge. Read the rubric ${P.judge} and follow it exactly.`,
    `Read the customer ticket ${tk.path}.`,
    'Judge the tone of each reply below on its own against the rubric. The replies come from different systems in random order. Do not guess which system wrote a reply. Do not judge label correctness.',
    'Return one verdict per reply_id with tone_pass and a one-sentence reason that quotes the reply.',
    ...order.map((t, i) => `--- reply_id R${i + 1} ---\n${t.out.reply}`),
  ].join('\n');
}

// ---------- Code checks ----------
function outsideAllowed(paths, t) {
  const allow = allowedFor(t);
  return (paths || []).filter(p => p.includes('spe/') && !allow.some(a => p.includes(a)));
}
function voidTrial(t, reason, rawPaths = []) {
  t.status = 'void';
  t.reasons.push(reason);
  if (rawPaths.some(p => LEAK_MARKERS.some(m => p.includes(m)))) halt(`answer key or grader exposed to trial ${t.nonce}`);
}
function codeCheck(t) {
  const o = t.out;
  if (!o) { t.status = 'error'; t.reasons.push('no structured output'); return; }
  const problems = [];
  if (o.nonce !== t.nonce) problems.push('nonce mismatch');
  if (o.config !== t.config) problems.push('config mismatch');
  if (o.ticket_id !== t.ticket) problems.push('ticket mismatch');
  if (!o.label || !o.label.category || !o.label.priority) problems.push('missing label field');
  if (typeof o.reply !== 'string' || !o.reply.trim()) problems.push('empty reply');
  if (problems.length) { t.status = 'invalid'; t.reasons.push(...problems); return; }
  const outside = outsideAllowed(o.files_read, t);
  if (outside.length) voidTrial(t, `self-reported reads outside allowed paths: ${outside.join(', ')}`, o.files_read);
}

// ---------- Stages ----------
async function runTrial(cell, n, phaseName, batch) {
  const what = `${cell.config}/${cell.ticket} t${n}`;
  const t = { config: cell.config, ticket: cell.ticket, path: cell.path, n, batch,
    nonce: `spe-${RUN_ID}-${cell.config}-${cell.ticket}-t${n}`, status: 'ok', reasons: [], out: null };
  if (haltReason) { t.status = 'skipped'; t.reasons.push('halted'); return t; }
  if (!reserve('trial', COST.trial, what)) { t.status = 'skipped'; t.reasons.push('budget cap'); return t; }
  t.out = await call(trialPrompt(t), { label: `trial ${what}`, phase: phaseName, schema: TRIAL_SCHEMA, model: TRIAL_MODEL });
  codeCheck(t);
  return t;
}

async function scan(trials, phaseName) {
  const todo = trials.filter(t => t.status === 'ok');
  const batches = chunk(todo, SCAN_BATCH);
  await parallel(batches.map((b, i) => async () => {
    if (!reserve('scan', COST.scanBatch, `batch ${i + 1}`, true)) { b.forEach(t => voidTrial(t, 'unscanned: budget cap')); return; }
    const res = await call(scanPrompt(b), { label: `peek scan ${i + 1}/${batches.length}`, phase: phaseName, schema: SCAN_SCHEMA, model: HELPER_MODEL });
    const byNonce = new Map(((res && res.results) || []).map(r => [r.nonce, r]));
    for (const t of b) {
      const r = byNonce.get(t.nonce);
      if (!r || !r.transcript_found) { voidTrial(t, 'unverified: transcript not found'); continue; }
      const outside = outsideAllowed(r.outside_reads, t);
      if (outside.length) voidTrial(t, `transcript shows reads outside allowed paths: ${outside.join(', ')}`, r.outside_reads);
    }
  }));
  const unverified = todo.filter(t => t.reasons.some(x => x.startsWith('unverified'))).length;
  if (todo.length && unverified / todo.length > 0.1) halt(`peek scan could not find ${unverified} of ${todo.length} trial transcripts`);
  log(`peek scan: ${todo.filter(t => t.status === 'void').length} voided of ${todo.length}`);
}

async function grade(trials, tag, phaseName) {
  const todo = trials.filter(t => t.status === 'ok');
  await parallel(CONFIGS.map(config => async () => {
    const mine = todo.filter(t => t.config === config);
    if (!mine.length || haltReason) return;
    if (!reserve('grade', COST.grade, `${config} ${tag}`, true)) { halt(`no budget left to grade ${config} ${tag}`); return; }
    const records = mine.map(t => ({ nonce: t.nonce, ticket_id: t.ticket, category: t.out.label.category, priority: t.out.label.priority }));
    const res = await call(gradePrompt(config, tag, records), { label: `grade ${config} ${tag}`, phase: phaseName, schema: GRADE_SCHEMA, model: HELPER_MODEL });
    if (!res) { halt(`grader agent failed for ${config} ${tag}`); return; }
    if (res.exit_code !== 0) { halt(`grade.py exited ${res.exit_code} for ${config} ${tag}: ${res.stderr_tail}`); return; }
    const byNonce = new Map(res.results.map(r => [r.nonce, r]));
    const mineSet = new Set(mine.map(t => t.nonce));
    const missing = mine.filter(t => !byNonce.has(t.nonce)).length;
    const unknown = res.results.filter(r => !mineSet.has(r.nonce)).length;
    if (missing || unknown) { halt(`grader returned ${missing} missing and ${unknown} unknown records for ${config} ${tag}`); return; }
    for (const t of mine) {
      const r = byNonce.get(t.nonce);
      t.categoryOk = r.category_ok;
      t.priorityOk = r.priority_ok;
      t.bothOk = r.category_ok && r.priority_ok;
    }
    log(`grade ${config} ${tag}: ${res.summary_line}`);
  }));
}

function cellWeighted(valid, key) {
  const groups = new Map();
  for (const t of valid) { const k = cellKey(t); if (!groups.has(k)) groups.set(k, []); groups.get(k).push(t[key]); }
  const rates = [...groups.values()].map(rate).filter(r => r !== null);
  return rates.length ? rates.reduce((a, b) => a + b, 0) / rates.length : null;
}

function summarize(allTrials, cells) {
  const out = {};
  for (const config of CONFIGS) {
    const mine = allTrials.filter(t => t.config === config);
    const valid = mine.filter(t => t.status === 'ok' && typeof t.bothOk === 'boolean');
    const base = valid.filter(t => t.batch === 'base');
    const metric = key => ({
      pooled_base: rate(base.map(t => t[key])),
      cell_weighted: cellWeighted(valid, key),
      n_base: base.filter(t => typeof t[key] === 'boolean').length,
      n_all: valid.filter(t => typeof t[key] === 'boolean').length,
    });
    const count = s => mine.filter(t => t.status === s).length;
    out[config] = {
      category_acc: metric('categoryOk'),
      priority_acc: metric('priorityOk'),
      both_acc: metric('bothOk'),
      tone_pass: metric('tonePass'),
      counts: {
        launched: mine.length - count('skipped'), valid: valid.length,
        void: count('void'), invalid: count('invalid'), error: count('error'), skipped: count('skipped'),
        split_cells: cells.filter(c => c.config === config && c.split).length,
      },
    };
  }
  return out;
}

function compact(t) {
  return {
    nonce: t.nonce, config: t.config, ticket: t.ticket, n: t.n, batch: t.batch, status: t.status, reasons: t.reasons,
    category: t.out && t.out.label ? t.out.label.category : null,
    priority: t.out && t.out.label ? t.out.label.priority : null,
    category_ok: t.categoryOk ?? null, priority_ok: t.priorityOk ?? null, tone_pass: t.tonePass ?? null,
    tools_called: t.out ? (t.out.tools_called || []) : [],
  };
}

// ---------- Run ----------
log(`SPE ${R} eval. run_id ${RUN_ID}.${DRY ? ' DRY RUN.' : ''} Spend figures are estimates, not metered spend.`);

phase('Preflight');
if (!DRY && A.gatesPassed !== true) halt('args.gatesPassed is not true. Run the grader selftest, the control regrade, and the dry run first.');
let pre = null;
if (!haltReason && reserve('helper', COST.helper, 'preflight')) {
  pre = await call(preflightPrompt(), { label: 'preflight', phase: 'Preflight', schema: PRE_SCHEMA, model: HELPER_MODEL });
}
if (!haltReason) {
  if (!pre) halt('preflight agent failed');
  else {
    if (!pre.prediction_committed || !pre.prediction_clean || !pre.plan_committed) halt(`prediction or plan is not committed and clean: ${pre.notes}`);
    const missingCfg = CONFIGS.filter(c => !pre.configs_present.includes(c));
    if (missingCfg.length) halt(`config folders missing: ${missingCfg.join(', ')}`);
    if (!DRY && pre.tickets.length !== EXPECTED_TICKETS) halt(`found ${pre.tickets.length} tickets, expected ${EXPECTED_TICKETS}`);
  }
}
const ticketPath = new Map(((pre && pre.tickets) || []).map(t => [t.id, t.path]));
const rawCells = haltReason ? [] : (DRY ? A.dryRunCells : CONFIGS.flatMap(config => pre.tickets.map(tk => ({ config, ticket: tk.id }))));
const cells = rawCells.map(c => ({ config: c.config, ticket: c.ticket, path: ticketPath.get(c.ticket), split: false }));
const badCells = cells.filter(c => !c.path || !CONFIGS.includes(c.config));
if (badCells.length) halt(`unknown cells: ${badCells.map(cellKey).join(', ')}`);
const ticketList = [...new Map(cells.map(c => [c.ticket, { id: c.ticket, path: c.path }])).values()];

ledger.held =
  (Math.ceil((cells.length * TRIALS_PER_CELL) / SCAN_BATCH) + 2) * COST.scanBatch +
  CONFIGS.length * 2 * COST.grade +
  ticketList.length * COST.judgeBatch +
  3 * COST.helper;
const projectedBase = cells.length * TRIALS_PER_CELL * COST.trial;
if (!haltReason && ledger.estSpent + ledger.held + projectedBase > CAP_USD && A.allowPartialGrid !== true) {
  halt(`est base grid $${projectedBase.toFixed(2)} plus $${ledger.held.toFixed(2)} held plus $${ledger.estSpent.toFixed(2)} spent exceeds the $${CAP_USD} cap. This decision belongs to the user.`);
}
log(`plan: ${cells.length} cells x ${TRIALS_PER_CELL} trials. est base $${projectedBase.toFixed(2)}, held $${ledger.held.toFixed(2)}.`);

phase('Trials');
const allTrials = [];
const baseJobs = [];
for (let n = 1; n <= TRIALS_PER_CELL; n++) for (const cell of cells) baseJobs.push([cell, n]); // trial-major order spreads any skips evenly
allTrials.push(...await parallel(baseJobs.map(([cell, n]) => () => runTrial(cell, n, 'Trials', 'base'))));
log(`base trials: ${allTrials.filter(t => t.status === 'ok').length} ok of ${allTrials.length}`);

phase('Peek scan');
if (!haltReason) await scan(allTrials, 'Peek scan');

phase('Code grade');
if (!haltReason) await grade(allTrials, 'base', 'Code grade');

phase('Split cells');
if (!haltReason) {
  const extraJobs = [];
  for (const cell of cells) {
    const ts = allTrials.filter(t => cellKey(t) === cellKey(cell));
    const valid = ts.filter(t => t.status === 'ok' && typeof t.bothOk === 'boolean');
    cell.split = valid.some(t => t.bothOk) && valid.some(t => !t.bothOk);
    const target = cell.split ? MAX_TRIALS_PER_CELL : TRIALS_PER_CELL; // split cells grow, short cells refill once
    const need = Math.max(0, target - valid.length);
    for (let k = 0; k < need; k++) extraJobs.push([cell, ts.length + 1 + k, k]);
  }
  extraJobs.sort((a, b) => a[2] - b[2]);
  log(`split cells: ${cells.filter(c => c.split).length}. extra or refill trials wanted: ${extraJobs.length}`);
  if (extraJobs.length) {
    const extras = await parallel(extraJobs.map(([cell, n]) => () => runTrial(cell, n, 'Split cells', 'extra')));
    allTrials.push(...extras);
    if (!haltReason) await scan(extras, 'Split cells');
    if (!haltReason) await grade(extras, 'extra', 'Split cells');
  }
}

phase('Tone judge');
if (!haltReason) {
  await parallel(ticketList.map(tk => async () => {
    const ts = allTrials.filter(t => t.ticket === tk.id && t.status === 'ok' && typeof t.bothOk === 'boolean');
    if (!ts.length || haltReason) return;
    if (!reserve('judge', COST.judgeBatch, tk.id, true)) return;
    const order = shuffled(ts, `${RUN_ID}-${tk.id}`);
    const idOf = new Map(order.map((t, i) => [`R${i + 1}`, t]));
    const res = await call(judgePrompt(tk, order), { label: `judge ${tk.id}`, phase: 'Tone judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL });
    for (const v of ((res && res.verdicts) || [])) {
      const t = idOf.get(v.reply_id);
      if (t) { t.tonePass = v.tone_pass; t.toneReason = v.reason; }
    }
    const missing = order.filter(t => typeof t.tonePass !== 'boolean').length;
    if (missing) log(`judge ${tk.id}: ${missing} replies have no verdict`);
  }));
}

const metrics = summarize(allTrials, cells);

phase('Failure analysis');
let failureAnalysis = null;
if (!haltReason) {
  const failed = allTrials.filter(t => t.status === 'ok' && (t.bothOk === false || t.tonePass === false));
  const step = Math.max(1, Math.ceil(failed.length / FAIL_SAMPLE_CAP));
  const sample = failed.filter((_, i) => i % step === 0);
  const notOk = allTrials.filter(t => ['void', 'invalid', 'error'].includes(t.status));
  if ((sample.length || notOk.length) && reserve('helper', COST.helper, 'failure analysis', true)) {
    failureAnalysis = await call([
      `SPE ${R} failure analysis. ${failed.length} trials failed a code check or the tone judge. ${sample.length} of them are listed below. ${notOk.length} trials were voided, invalid, or errored, and they are listed after that.`,
      `Read ${P.failures} for the failure types already named (F-numbers). You may read ${P.answers}, ${P.tickets}, and ${P.configs} to find causes.`,
      'Group the failures into types. Reuse an existing F-number when it fits, and say why it fits. Set is_new when none fits. Give each type a name, a kind, a count per config, example nonces, what happens, how to spot it, and a fix.',
      'Put any trial where the label looks right in meaning but the grader marked it wrong, or where the grader looks wrong in any other way, under grader_suspects. A grader bug counts as a failure.',
      'Do not edit any file.',
      'Failed trials:',
      ...sample.map(t => JSON.stringify({ ...compact(t), judge_reason: t.toneReason || null, reply_excerpt: (t.out.reply || '').slice(0, 400) })),
      'Voided, invalid, or errored trials:',
      ...notOk.map(t => JSON.stringify(compact(t))),
    ].join('\n'), { label: 'failure analysis', phase: 'Failure analysis', schema: FAIL_SCHEMA, model: HELPER_MODEL });
    if (failureAnalysis && failureAnalysis.grader_suspects.length) log(`grader suspects: ${failureAnalysis.grader_suspects.length}. Review them before close-out.`);
  }
}

phase('Completeness critic');
const summary = {
  round: ROUND, run_id: RUN_ID, dry_run: DRY, halted: haltReason, metrics,
  est_spend_usd: Number(ledger.estSpent.toFixed(2)), cap_usd: CAP_USD, skips: ledger.skips,
  failure_types: failureAnalysis ? failureAnalysis.failure_types.map(f => ({ id: f.id, is_new: f.is_new, name: f.name, counts: f.counts })) : null,
};
let critic = null;
if (reserve('helper', COST.helper, 'completeness critic', true)) {
  critic = await call([
    `SPE ${R} completeness critic. Read ${P.prediction}. Compare it with the run summary below.`,
    'List every predicted metric and config that has no measured number in the summary.',
    `Check that every cell has at least ${TRIALS_PER_CELL} valid trials, or that the summary explains why not through voids, skips, or a halt.`,
    'Check that voids, skips, halts, and estimated spend are all reported, and that the failure types account for the failed trials.',
    'Report gaps as plain sentences. Set complete to true only when there are no gaps. Do not edit any file.',
    JSON.stringify(summary),
  ].join('\n'), { label: 'completeness critic', phase: 'Completeness critic', schema: CRITIC_SCHEMA, model: HELPER_MODEL });
}

phase('Record');
const results = { ...summary, failure_analysis: failureAnalysis, critic, trials: allTrials.map(compact) };
let record = null;
if (reserve('helper', COST.helper, 'record', true)) {
  record = await call([
    `SPE ${R} record. Write the JSON below to ${P.results} exactly as given, and create folders as needed. Do not change it. Do not commit.`,
    JSON.stringify(results),
  ].join('\n'), { label: 'record', phase: 'Record', schema: RECORD_SCHEMA, model: HELPER_MODEL });
}
if (!record || !record.ok) log(`results file was not written. The full results are in this run's return value.`);

return {
  ...summary,
  critic,
  grader_suspects: failureAnalysis ? failureAnalysis.grader_suspects : [],
  voided: allTrials.filter(t => t.status === 'void').map(t => ({ nonce: t.nonce, reasons: t.reasons })),
  results_file: record && record.ok ? P.results : null,
};
